package Work;

public class Elseifladderwork3 {

	public static void main(String[] args) {
		// TODO Auto-generated method stub
		int num=100;
		if (num > 100) {
			System.out.println("Greater than 100");
		}
		else if (num < 100) {
			System.out.println("Less than 100");
		}
		else if (num==100) {
			System.out.println("Equal to 100");
		}

	}

}
